css:
.comp-adv-container { padding: 24px; background: #faf8f3; min-height: 100vh; font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif; color: #1a2744; max-width: 1400px; margin: 0 auto; }
.comp-adv-header { background: linear-gradient(135deg, #264653 0%, #1a2744 100%); color: #faf8f3; padding: 32px 40px; border-radius: 4px; margin-bottom: 24px; box-shadow: 0 4px 16px rgba(26,39,68,0.18); }
.comp-adv-header h1 { font-size: 1.8rem; font-weight: 700; margin: 0; letter-spacing: 0.02em; }
.comp-adv-subtitle { color: #f4c693; margin-top: 6px; font-size: 0.95rem; font-style: italic; }
.comp-adv-period-counter { background: #1a2744; color: #f4a261; padding: 12px 24px; border-radius: 4px; font-weight: 700; text-align: center; margin-bottom: 24px; font-size: 1.05rem; letter-spacing: 0.08em; text-transform: uppercase; }
.comp-adv-briefing { background: #ffffff; border-left: 4px solid #f4a261; padding: 20px 24px; border-radius: 4px; margin-bottom: 24px; box-shadow: 0 2px 8px rgba(38,70,83,0.08); }
.comp-adv-briefing-label { font-size: 0.72rem; color: #6b7280; letter-spacing: 0.12em; text-transform: uppercase; margin-bottom: 8px; font-weight: 700; }
.comp-adv-briefing-text { font-size: 1rem; color: #1a2744; line-height: 1.6; }
.comp-adv-briefing-text strong { color: #b54a30; }
.comp-adv-countries { display: grid; grid-template-columns: 1fr 1fr; gap: 24px; margin-bottom: 24px; }
.comp-adv-country { background: #ffffff; border-radius: 4px; padding: 24px; box-shadow: 0 2px 8px rgba(38,70,83,0.08); position: relative; border-top: 4px solid; }
.comp-adv-costaria { border-top-color: #e76f51; }
.comp-adv-boravia { border-top-color: #2a9d8f; }
.comp-adv-country-flag { font-size: 2rem; margin-bottom: 4px; line-height: 1; }
.comp-adv-country h2 { font-size: 1.3rem; font-weight: 700; margin: 0 0 12px 0; color: #1a2744; }
.comp-adv-costaria h2 { color: #b54a30; }
.comp-adv-boravia h2 { color: #1d6a60; }
.comp-adv-country-meta { display: flex; gap: 18px; font-size: 0.85rem; color: #6b7280; margin-bottom: 12px; }
.comp-adv-country-rates { background: #f8f5ee; padding: 12px 16px; border-radius: 4px; font-size: 0.85rem; margin-bottom: 16px; line-height: 1.6; }
.comp-adv-opp-cost { font-weight: 700; margin-top: 6px; padding-top: 6px; border-top: 1px dashed #d4c8b0; color: #1a2744; }
.comp-adv-kpi-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; margin-bottom: 16px; }
.comp-adv-kpi-card { background: #f8f5ee; padding: 14px 16px; border-radius: 4px; border-left: 3px solid #c8b89a; }
.comp-adv-kpi-cons { border-left-color: #f4a261; background: #fef6ec; }
.comp-adv-boravia .comp-adv-kpi-cons { border-left-color: #2a9d8f; background: #ebf6f2; }
.comp-adv-kpi-label { font-size: 0.7rem; color: #6b7280; letter-spacing: 0.08em; text-transform: uppercase; margin-bottom: 4px; font-weight: 700; }
.comp-adv-kpi-value { font-size: 1.4rem; font-weight: 700; color: #1a2744; transition: color 0.2s ease; }
.comp-adv-decision { background: #f4eee0; padding: 14px 16px; border-radius: 4px; }
.comp-adv-decision label { display: block; font-size: 0.78rem; font-weight: 700; color: #1a2744; margin-bottom: 6px; letter-spacing: 0.04em; text-transform: uppercase; }
.comp-adv-decision input[type="range"] { width: 100%; margin: 8px 0; accent-color: #e76f51; }
.comp-adv-boravia .comp-adv-decision input[type="range"] { accent-color: #2a9d8f; }
.comp-adv-slider-value { font-size: 0.85rem; color: #6b7280; text-align: center; }
.comp-adv-trade-panel, .comp-adv-policy-panel { background: #ffffff; border-radius: 4px; padding: 24px; margin-bottom: 24px; box-shadow: 0 2px 8px rgba(38,70,83,0.08); border-top: 4px solid #1a2744; }
.comp-adv-trade-panel h3, .comp-adv-policy-panel h3, .comp-adv-world h3, .comp-adv-history h3 { margin: 0 0 12px 0; font-size: 1.05rem; font-weight: 700; color: #1a2744; letter-spacing: 0.04em; text-transform: uppercase; }
.comp-adv-trade-info, .comp-adv-policy-info { font-size: 0.9rem; color: #6b7280; margin-bottom: 16px; font-style: italic; line-height: 1.5; }
.comp-adv-trade-controls { display: grid; grid-template-columns: 1fr 1fr; gap: 16px; margin-bottom: 16px; }
.comp-adv-trade-input label { display: block; font-size: 0.78rem; font-weight: 700; color: #1a2744; margin-bottom: 6px; letter-spacing: 0.04em; text-transform: uppercase; }
.comp-adv-trade-input input { width: 100%; background: #faf8f3; border: 1px solid #c8b89a; color: #1a2744; padding: 10px 12px; border-radius: 4px; font-size: 1rem; font-family: inherit; }
.comp-adv-trade-input input:focus { outline: none; border-color: #f4a261; box-shadow: 0 0 0 2px rgba(244,162,97,0.2); }
.comp-adv-trade-output { background: #f8f5ee; padding: 12px 16px; border-radius: 4px; font-size: 0.95rem; display: flex; gap: 32px; flex-wrap: wrap; color: #1a2744; }
.comp-adv-trade-output strong { color: #b54a30; font-size: 1.05rem; }
.comp-adv-displaced-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; margin-bottom: 16px; }
.comp-adv-displaced-card { background: #fef6ec; padding: 14px 18px; border-radius: 4px; border-left: 3px solid #e76f51; }
.comp-adv-displaced-card:nth-child(2) { background: #ebf6f2; border-left-color: #2a9d8f; }
.comp-adv-displaced-label { font-size: 0.7rem; color: #6b7280; letter-spacing: 0.08em; text-transform: uppercase; margin-bottom: 4px; font-weight: 700; }
.comp-adv-displaced-value { font-size: 1.4rem; font-weight: 700; color: #b54a30; }
.comp-adv-displaced-card:nth-child(2) .comp-adv-displaced-value { color: #1d6a60; }
.comp-adv-policy-panel label { display: block; font-size: 0.78rem; font-weight: 700; color: #1a2744; margin-bottom: 6px; letter-spacing: 0.04em; text-transform: uppercase; }
.comp-adv-policy-panel select { width: 100%; background: #faf8f3; border: 1px solid #c8b89a; color: #1a2744; padding: 10px 12px; border-radius: 4px; font-size: 0.95rem; font-family: inherit; }
.comp-adv-policy-panel select:focus { outline: none; border-color: #f4a261; box-shadow: 0 0 0 2px rgba(244,162,97,0.2); }
.comp-adv-policy-panel select option { background: #ffffff; color: #1a2744; }
.comp-adv-world { background: #ffffff; border-radius: 4px; padding: 20px 24px; margin-bottom: 24px; box-shadow: 0 2px 8px rgba(38,70,83,0.08); border-top: 4px solid #2a9d8f; }
.comp-adv-world-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 16px; }
.comp-adv-world-card { background: #ebf6f2; padding: 18px 22px; border-radius: 4px; border-left: 3px solid #2a9d8f; }
.comp-adv-world-label { font-size: 0.72rem; color: #6b7280; letter-spacing: 0.1em; text-transform: uppercase; margin-bottom: 6px; font-weight: 700; }
.comp-adv-world-value { font-size: 1.7rem; font-weight: 700; color: #1d6a60; }
.comp-adv-actions { display: flex; gap: 12px; margin-bottom: 24px; align-items: center; }
.comp-adv-actions .btn-primary { background: #e76f51; border-color: #e76f51; font-weight: 700; letter-spacing: 0.06em; padding: 12px 28px; text-transform: uppercase; font-size: 0.85rem; border-radius: 4px; transition: background 0.2s ease, transform 0.2s ease; }
.comp-adv-actions .btn-primary:hover { background: #d65a3e; border-color: #d65a3e; transform: translateY(-1px); }
.comp-adv-actions .btn-outline-secondary { color: #6b7280; border-color: #c8b89a; background: transparent; font-size: 0.8rem; }
.comp-adv-actions .btn-outline-secondary:hover { background: #f8f5ee; color: #1a2744; }
.comp-adv-history { background: #ffffff; border-radius: 4px; padding: 20px 24px; margin-bottom: 24px; box-shadow: 0 2px 8px rgba(38,70,83,0.08); }
.comp-adv-history table { font-size: 0.85rem; color: #1a2744; margin-bottom: 0; }
.comp-adv-history table th { background: #1a2744; color: #faf8f3; font-weight: 700; letter-spacing: 0.06em; text-transform: uppercase; font-size: 0.7rem; padding: 10px 12px; border: none; }
.comp-adv-history table td { padding: 10px 12px; border-color: #ece4d3; }
.comp-adv-charts { display: grid; grid-template-columns: 1fr 1fr; gap: 24px; }
.comp-adv-chart-wrap { background: #ffffff; border-radius: 4px; padding: 16px; box-shadow: 0 2px 8px rgba(38,70,83,0.08); height: 340px; position: relative; }
@media (max-width: 768px) { .comp-adv-countries, .comp-adv-trade-controls, .comp-adv-displaced-grid, .comp-adv-world-grid, .comp-adv-charts { grid-template-columns: 1fr; } .comp-adv-container { padding: 16px; } .comp-adv-header { padding: 22px 24px; } .comp-adv-header h1 { font-size: 1.35rem; } .comp-adv-chart-wrap { height: 280px; } }

/* --- EQIL 2026-08-07: focus, motion, completion panel --- */
.comp-adv-container :focus-visible,
.comp-adv-container select:focus-visible,
.comp-adv-container input:focus-visible,
.comp-adv-container button:focus-visible {
    outline: 3px solid #264653;
    outline-offset: 2px;
    border-radius: 3px;
}
.comp-adv-actions { display: flex; gap: 12px; align-items: center; flex-wrap: wrap; }
.comp-adv-completion {
    background: #ffffff;
    border: 1px solid #e0dbcf;
    border-left: 6px solid #264653;
    border-radius: 4px;
    padding: 22px 26px;
    margin: 20px 0;
    color: #1a2744;
}
.comp-adv-debrief h3 { margin: 0 0 10px; font-size: 1.15rem; }
.comp-adv-debrief-headline { font-size: 1rem; margin-bottom: 14px; }
.comp-adv-debrief-list {
    list-style: none; padding: 0; margin: 0 0 14px;
    display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 8px;
}
.comp-adv-debrief-list li {
    display: flex; justify-content: space-between; gap: 12px;
    background: #faf8f3; border: 1px solid #e0dbcf; border-radius: 4px; padding: 8px 12px;
}
.comp-adv-debrief-k { color: #55606f; font-size: 0.82rem; }
.comp-adv-debrief-v { font-weight: 700; }
.comp-adv-debrief-insights p { margin: 0 0 8px; font-size: 0.9rem; line-height: 1.5; }
@media (prefers-reduced-motion: reduce) {
    .comp-adv-container *,
    .comp-adv-container *::before,
    .comp-adv-container *::after {
        animation-duration: 0.01ms !important;
        animation-iteration-count: 1 !important;
        transition-duration: 0.01ms !important;
        scroll-behavior: auto !important;
    }
}
/* 1220 v1.2.1 (EQIL 2026-10-30): visible keyboard focus, AA contrast on the submit button, Round 3 effect line, debrief sections */
.comp-adv-container input:focus-visible, .comp-adv-container select:focus-visible, .comp-adv-container button:focus-visible { outline: 3px solid #1a2744; outline-offset: 2px; }
.comp-adv-actions .btn-primary { background: #b54a30; border-color: #b54a30; color: #ffffff; }
.comp-adv-actions .btn-primary:hover { background: #8f3a25; border-color: #8f3a25; }
.comp-adv-policy-effect { margin-top: 10px; font-size: 0.9rem; color: #1a2744; background: #f8f5ee; border-left: 3px solid #c8b89a; padding: 8px 12px; border-radius: 4px; }
.comp-adv-policy-effect:empty { display: none; }
.comp-adv-debrief h4 { font-size: 0.95rem; margin: 14px 0 6px 0; color: #1a2744; }
.comp-adv-debrief-questions { padding-left: 20px; margin: 0; line-height: 1.5; }

js:
/* EQIL guard 1.3 (2026-10-08). Shared block, identical in every sim except SEED and MODE.
   1. Choice decisions start with no option selected and a seeded option order
      (MODE blank: empty selection, original order, for sims that address options by index).
   2. Render timers set while scoring a round wait until the period has advanced.
   3. getHint reads the round that was just scored.
   4. Where the runtime has no eventBus (Open player), a minimal one emits the platform events.
   5. Summary labels and insights returned as translation keys are translated for the platform default debrief.
   6. The framework t() is bound to its instance, so sims that copy it into a local variable keep working.
   7. (1.1) Checkboxes the view ticks by default start unticked until the player ticks them. A restored or
      resumed game keeps its ticks, disabled boxes are left alone, and a tick the player made is never cleared.
   8. (1.2) Text the sim wrote from its own translation table follows the language: after a switch, and whenever
      the sim writes text, a string from another language's table becomes the same key's string in the current one.
   9. (1.2) Randomness drawn while initialising or scoring comes from a generator kept in domainState, so undoing
      a round and submitting it again replays it exactly instead of re-rolling it.
  10. (1.2) Once the run is complete the submit button is disabled; an undo that reopens the run enables it again.
  11. (1.3) A choice keeps its order only when its texts read as a scale (a leading number, %, currency, or two level
      words). Numeric option values alone no longer count: many decisions with named options use 0, 1, 2 as values.
  12. (1.3) The seeded order also depends on the round, so options rebuilt each round are not in the same order
      every round. The same round (a redraw, a language switch, an undo, a resumed game) keeps its order.
   Reviews: Express/testing/eqil_reports/2026-09/EQIL_Portfolio_Finding_open-catalog-review_2026-09-28.md,
   2026-10/EQIL_Portfolio_Finding_model-sweep_2026-10-06.md (EQIL v1.2.0 §15, gates G-F and G-H) */
var __eqilGuard = (function () {
    var SEED = "1220";
    var MODE = "";   // blank: the sim addresses options by position, so no inserted placeholder and no shuffle; empty: placeholder and seeded shuffle
    var TXT = {
        en: ["Choose an option", "Choose an option in every decision before continuing."],
        es: ["Elige una opción", "Elige una opción en cada decisión antes de continuar."],
        ca: ["Tria una opció", "Tria una opció a cada decisió abans de continuar."],
        pt: ["Escolha uma opção", "Escolha uma opção em cada decisão antes de continuar."],
        fr: ["Choisissez une option", "Choisissez une option pour chaque décision avant de continuer."]
    };
    var LEVEL = ["none", "low", "medium", "moderate", "high", "very ", "minimal", "maximum", "conservative", "aggressive",
        "ningun", "bajo", "baja", "medio", "media", "moderad", "alto", "alta", "muy ", "mínim", "máxim", "conservador", "agresiv"];
    var later = window.setTimeout.bind(window);
    var submitted = null;
    var lastRound = null;
    var queued = false;
    var styled = false;
    var groups = {};
    var restoring = false;
    var resumed = false;

    var bus = null;
    function sim() { return window.mySimulation || null; }
    function miniBus() {
        var h = {};
        return {
            on: function (n, f) { (h[n] = h[n] || []).push(f); },
            off: function (n, f) { var a = h[n] || [], k = a.indexOf(f); if (k >= 0) { a.splice(k, 1); } },
            emit: function (n, d) { var a = (h[n] || []).slice(); for (var i = 0; i < a.length; i++) { try { a[i](d); } catch (e) {} } }
        };
    }
    function polyfill(f) {
        if (!f || f.eventBus) { return; }
        bus = miniBus();
        f.eventBus = bus;
        if (typeof f.undo === "function") {
            var u = f.undo;
            f.undo = function () { var r = u.apply(this, arguments); bus.emit("period:undone", this.state); return r; };
        }
        if (typeof f.setLang === "function") {
            var sl = f.setLang;
            f.setLang = function (l) {
                var r = sl.apply(this, arguments);
                bus.emit("language:changed", { lang: l });
                try { document.dispatchEvent(new CustomEvent("express:langchanged", { detail: { lang: l } })); } catch (e) {}
                return r;
            };
        }
    }
    function announce(state, res) {
        if (!bus || !state) { return; }
        var p0 = state.currentPeriod, t0 = Date.now();
        (function check() {
            if (String(state.currentPeriod) !== String(p0) || Date.now() - t0 > 4000) { bus.emit("period:submitted", { results: res, period: p0 }); }
            else { later(check, 40); }
        })();
    }
    function lang() {
        var l = "";
        try { if (window.vcI18n && window.vcI18n._lang) { l = window.vcI18n._lang; } } catch (e) {}
        try { if (!l && sim() && sim().lang) { l = sim().lang; } } catch (e) {}
        if (!l) { l = document.documentElement.lang || "en"; }
        l = String(l).toLowerCase().slice(0, 2);
        return TXT[l] ? l : "en";
    }
    function roundKey() { var f = sim(); return f && f.state ? String(f.state.currentPeriod) : ""; }
    function hash(s) {
        var h = 2166136261;
        for (var i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 16777619); }
        return h >>> 0;
    }
    function rand(seed) {
        var a = seed;
        return function () {
            a = (a + 0x6D2B79F5) | 0;
            var t = Math.imul(a ^ (a >>> 15), 1 | a);
            t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
            return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
        };
    }
    function permute(items, key) {
        var r = rand(hash(key)), a = items.slice();
        for (var i = a.length - 1; i > 0; i--) { var j = Math.floor(r() * (i + 1)); var t = a[i]; a[i] = a[j]; a[j] = t; }
        return a;
    }
    function gameKey(name, values) {
        // 1.3: the round is part of the key, so a select rebuilt every round with the same id and values gets a new
        // order each round (1422 kept one order for all 9 rounds, so always picking the second option scored 88)
        var f = sim(), g = f && f.state && f.state.gameId;
        return SEED + "|" + (g || "") + "|" + roundKey() + "|" + name + "|" + values.join(",");
    }
    function shown(el) {
        for (var n = el; n && n.nodeType === 1; n = n.parentElement) {
            if (n.hidden || n.id === "usfp-overlay") { return false; }
            var cs = window.getComputedStyle ? window.getComputedStyle(n) : null;
            if (cs && (cs.display === "none" || cs.visibility === "hidden")) { return false; }
        }
        return true;
    }
    function skipped(el) {
        if (el.getAttribute("data-eqil-skip") !== null) { return true; }
        return !!(el.closest && el.closest("#usfp-overlay"));
    }
    function ordinal(texts, values) {
        // 1.3: only the texts decide. Numeric values alone (0, 1, 2) no longer keep a decision in order: many
        // decisions with named options use them, and a fixed order there let the first or last option win.
        var nt = 0, lv = 0;
        for (var i = 0; i < texts.length; i++) {
            var t = String(texts[i]).trim().toLowerCase(), c = t.charAt(0);
            if ((c >= "0" && c <= "9") || c === "$" || c === "€" || c === "£" || c === "+" || c === "-" || t.indexOf("%") >= 0) { nt++; }
            for (var k = 0; k < LEVEL.length; k++) { if (t.indexOf(LEVEL[k]) === 0) { lv++; break; } }
        }
        return nt * 2 >= texts.length || lv >= 2;
    }
    var PH_WORDS = ["select", "selec", "elig", "elij", "escog", "escoj", "choose", "pick one", "tria ", "escolh", "choisi"];
    function isPlaceholder(o) {
        if (o.value === "") { return true; }
        var t = String(o.textContent || "").trim().toLowerCase(), c = t.charAt(0), k;
        if (!(c === "-" || c === "—" || c === "–" || c === "." || c === "…")) { return false; }
        for (k = 0; k < PH_WORDS.length; k++) { if (t.indexOf(PH_WORDS[k]) >= 0) { return true; } }
        for (k = 0; k < t.length; k++) { if ("-—–.… ".indexOf(t.charAt(k)) < 0) { return false; } }
        return true;
    }
    function clear(sel, ph) {
        if (ph) { sel.value = ph.value; } else { sel.selectedIndex = -1; }
    }
    function hasValue(sel, v) {
        for (var i = 0; i < sel.options.length; i++) { if (sel.options[i].value === v) { return true; } }
        return false;
    }

    /* 8. Text follows the language. The tables are the sim's own (vcI18n on the platform, .trans in the
       Open player). A string is replaced only when it is another language's value for a key the current
       language also has, and never when it is also a value of the current language itself. */
    var trCache = { lang: null, maps: null };
    function rawLang() {
        var l = "";
        try { if (window.vcI18n && window.vcI18n._lang) { l = window.vcI18n._lang; } } catch (e) {}
        try { if (!l && sim() && sim().lang) { l = sim().lang; } } catch (e) {}
        if (!l) { l = document.documentElement.lang || "en"; }
        return String(l).toLowerCase().slice(0, 2);
    }
    function tables() {
        try { if (window.vcI18n && window.vcI18n._translations && typeof window.vcI18n._translations === "object") { var t = window.vcI18n._translations; for (var k in t) { if (t[k] && typeof t[k] === "object") { return t; } } } } catch (e) {}
        try { var f = sim(); if (f && f.trans && typeof f.trans === "object") { return f.trans; } } catch (e) {}
        return null;
    }
    function flat(o, pre, out, d) {
        if (!o || typeof o !== "object" || d > 4) { return out; }
        for (var k in o) {
            if (!Object.prototype.hasOwnProperty.call(o, k)) { continue; }
            var v = o[k];
            if (typeof v === "string") { out[pre + k] = v; }
            else if (v && typeof v === "object" && !Array.isArray(v)) { flat(v, pre + k + ".", out, d + 1); }
        }
        return out;
    }
    function squash(s) { return String(s).replace(/\s+/g, " ").replace(/^ | $/g, ""); }
    var decoder = null;
    function decode(s) {
        if (s.indexOf("&") < 0) { return s; }
        try { decoder = decoder || document.createElement("textarea"); decoder.innerHTML = s; return decoder.value; } catch (e) { return s; }
    }
    // a value with inline markup is several text nodes on the page: one piece per stretch between tags
    function pieces(v) {
        var p = String(v).split(/<[^>]*>/);
        for (var i = 0; i < p.length; i++) { p[i] = decode(p[i]); }
        return p;
    }
    var LETTER = /[A-Za-zÀ-ɏ]/;
    function quote(s) { return s.replace(/[.*+?^$()|[\]\\]/g, "\\$&"); }
    function template(a, b) {
        var parts = a.split(/\{(\w+)\}/), names = [], rx = "", lit = 0;
        for (var i = 0; i < parts.length; i++) {
            if (i % 2) { names.push(parts[i]); rx += (i === parts.length - 2 && parts[i + 1] === "") ? "([^\\s.,;:!?)]+)" : "(.+?)"; }
            else { rx += quote(parts[i]); lit += parts[i].replace(/\s/g, "").length; }
