            var psel = document.getElementById('policySelect');
            if (psel && state.decisions.policy) psel.value = state.decisions.policy;
            this._wireSliders();
            this._refreshSliderLabels();
            this._updateBriefing(state);
            this._syncControlsFromDecisions(state);
        }

        _wireSliders() {
            var self = this;
            var costSlider = document.getElementById('costariaMangoPctInput');
            var boraSlider = document.getElementById('boraviaMangoPctInput');
            var costPct = document.getElementById('costariaPctDisplay');
            var costSoftPct = document.getElementById('costariaSoftPctDisplay');
            var boraPct = document.getElementById('boraviaPctDisplay');
            var boraSoftPct = document.getElementById('boraviaSoftPctDisplay');
            if (costSlider && costPct && costSoftPct) {
                costSlider.addEventListener('input', function() {
                    costPct.textContent = this.value;
                    costSoftPct.textContent = (100 - parseFloat(this.value)).toFixed(0);
                    self._updateTradePreview();
                });
            }
            if (boraSlider && boraPct && boraSoftPct) {
                boraSlider.addEventListener('input', function() {
                    boraPct.textContent = this.value;
                    boraSoftPct.textContent = (100 - parseFloat(this.value)).toFixed(0);
                    self._updateTradePreview();
                });
            }
            ['tradePriceInput', 'mangoesExportedInput'].forEach(function(id) {
                var el = document.getElementById(id);
                if (el) el.addEventListener('input', function() { self._updateTradePreview(); });
            });
            var psel = document.getElementById('policySelect');
            if (psel) psel.addEventListener('change', function() { self._updateTradePreview(); });
            if (!this._uiBound) {
                this._uiBound = true;
                // an undo puts the screen back on the round being replayed (the engine does not call the adapter)
                try {
                    if (window.mySimulation && window.mySimulation.eventBus && typeof window.mySimulation.eventBus.on === 'function') {
                        window.mySimulation.eventBus.on('period:undone', function() {
                            var st = window.mySimulation.state || {};
                            self._updateBriefing({ currentPeriod: st.currentPeriod || 1 });
                            self._refreshSliderLabels();
                        });
                    }
                } catch (e) {}
                document.addEventListener('express:langchanged', function() { try { self._updateTradePreview(); } catch (e) {} });
            }
        }

        _refreshSliderLabels() {
            var costSlider = document.getElementById('costariaMangoPctInput');
            var boraSlider = document.getElementById('boraviaMangoPctInput');
            var costPct = document.getElementById('costariaPctDisplay');
            var costSoftPct = document.getElementById('costariaSoftPctDisplay');
            var boraPct = document.getElementById('boraviaPctDisplay');
            var boraSoftPct = document.getElementById('boraviaSoftPctDisplay');
            if (costSlider && costPct && costSoftPct) {
                costPct.textContent = costSlider.value;
                costSoftPct.textContent = (100 - parseFloat(costSlider.value)).toFixed(0);
            }
            if (boraSlider && boraPct && boraSoftPct) {
                boraPct.textContent = boraSlider.value;
                boraSoftPct.textContent = (100 - parseFloat(boraSlider.value)).toFixed(0);
            }
            this._updateTradePreview();
        }

        _updateTradePreview() {
            if (!window.mySimulation || !window.mySimulation.state) return;
            var period = window.mySimulation.state.currentPeriod || 1;
            if (period < 2) return;
            var tpEl = document.getElementById('tradePriceInput');
            var meEl = document.getElementById('mangoesExportedInput');
            var costEl = document.getElementById('costariaMangoPctInput');
            if (!tpEl || !meEl || !costEl) return;
            var tpBlank = String(tpEl.value).trim() === '' || isNaN(parseFloat(tpEl.value));
            var tp = tpBlank ? 0 : parseFloat(tpEl.value);
            var me = parseFloat(meEl.value) || 0;
            var costMangoPct = parseFloat(costEl.value) || 0;
            var costMangoProd = (costMangoPct / 100) * 1000000 * 100;
            var actualExport = Math.min(me * 1000000, costMangoProd);
            var importSoft = tp > 0 ? actualExport / tp : 0;
            var exDisp = document.getElementById('tradeExportDisplay');
            var imDisp = document.getElementById('tradeImportDisplay');
            if (exDisp) exDisp.textContent = (actualExport / 1000000).toFixed(1) + 'M';
            if (imDisp) imDisp.textContent = tpBlank ? '—' : (importSoft / 1000000).toFixed(1) + 'M';
            if (period >= 3) this._previewRound3();
        }

        /* Round 3 panel: displaced counts follow the sliders, and the chosen mechanism states what it does (display only) */
        _previewRound3() {
            var sim = window.mySimulation;
            if (!sim || !sim.state || !sim.state.domainState) return;
            var b = sim.state.domainState.autarkyBaseline;
            var costEl = document.getElementById('costariaMangoPctInput');
            var boraEl = document.getElementById('boraviaMangoPctInput');
            var loc = this._lang() === 'es' ? 'es-ES' : 'en-US';
            if (b && costEl && boraEl) {
                var cd = Math.abs((parseFloat(costEl.value) / 100) * 1000000 - b.costMangoW);
                var bd = Math.abs((parseFloat(boraEl.value) / 100) * 10000000 - b.boraMangoW);
                var cdEl = document.getElementById('costariaDisplacedDisplay');
                var bdEl = document.getElementById('boraviaDisplacedDisplay');
                if (cdEl && !isNaN(cd)) cdEl.textContent = Math.round(cd).toLocaleString(loc);
                if (bdEl && !isNaN(bd)) bdEl.textContent = Math.round(bd).toLocaleString(loc);
            }
            var out = document.getElementById('policyEffectDisplay');
            var sel = document.getElementById('policySelect');
            if (!out || !sel) return;
            var pol = sel.value;
            var tpEl = document.getElementById('tradePriceInput');
            var meEl = document.getElementById('mangoesExportedInput');
            var p = tpEl ? parseFloat(tpEl.value) : NaN;
            var cmp = costEl ? parseFloat(costEl.value) : 0;
            var X = Math.min(meEl ? (parseFloat(meEl.value) || 0) : 0, cmp);
            var g = this._gains(X, p);
            var gains = Math.max(0, g.c) + Math.max(0, g.b);
            var pct = { a: 8, b: 12, c: 15 }[pol];
            if (pct) out.textContent = this._fill('policy_effect_abc', { pct: pct, v: this._num(gains * pct / 100, 1) });
            else if (pol === 'd') out.textContent = this._t('policy_effect_d');
            else if (pol === 'e') out.textContent = this._t('policy_effect_e');
            else out.textContent = '';
        }

        validateDecisions(decisions) {
            var period = window.mySimulation.state.currentPeriod;
            var costEl = document.getElementById('costariaMangoPctInput');
            var boraEl = document.getElementById('boraviaMangoPctInput');
            var cmw = costEl ? parseFloat(costEl.value) : NaN;
            var bmw = boraEl ? parseFloat(boraEl.value) : NaN;
            if (isNaN(cmw) || cmw < 0 || cmw > 100) {
                window.mySimulation.uiManager.showNotification(window.mySimulation.t('warn_costaria_pct'), 'warning');
                return false;
            }
            if (isNaN(bmw) || bmw < 0 || bmw > 100) {
                window.mySimulation.uiManager.showNotification(window.mySimulation.t('warn_boravia_pct'), 'warning');
                return false;
            }
            decisions.costariaMangoPct = cmw;
            decisions.boraviaMangoPct = bmw;
            if (period >= 2) {
                var tpEl = document.getElementById('tradePriceInput');
                var meEl = document.getElementById('mangoesExportedInput');
                var tp = (tpEl && String(tpEl.value).trim() !== '') ? parseFloat(tpEl.value) : NaN;
                var me = meEl ? parseFloat(meEl.value) : NaN;
                if (!tpEl || String(tpEl.value).trim() === '') {
                    window.mySimulation.uiManager.showNotification(window.mySimulation.t('warn_trade_price_blank'), 'warning');
                    return false;
                }
                if (isNaN(tp) || tp < 0.5 || tp > 3) {
                    window.mySimulation.uiManager.showNotification(window.mySimulation.t('warn_trade_price'), 'warning');
                    return false;
                }
                if (isNaN(me) || me < 0) {
                    window.mySimulation.uiManager.showNotification(window.mySimulation.t('warn_export'), 'warning');
                    return false;
                }
                decisions.tradePrice = tp;
                decisions.mangoesExported = me;
            } else {
                decisions.tradePrice = 0;
                decisions.mangoesExported = 0;
            }
            if (period >= 3) {
                var sel = document.getElementById('policySelect');
                if (sel) decisions.policy = sel.value;
            }
            return true;
        }

        calculateResults(state) {
            var r = this._computeRound(state);
            return r;
        }

        /* the round model; calculateResults stays a thin wrapper (EQIL defect family item 1) */
        _computeRound(state) {
            var d = state.decisions;
            var period = state.currentPeriod;
            var ds = state.domainState;
            ['shippedHistory', 'priceHistory', 'costShareHistory', 'boraShareHistory'].forEach(function(k) { if (!Array.isArray(ds[k])) ds[k] = []; });
            var costMangoW = (d.costariaMangoPct / 100) * 1000000;
            var costSoftW = 1000000 - costMangoW;
            var costMangoProd = costMangoW * 100;
            var costSoftProd = costSoftW * 50;
            var boraMangoW = (d.boraviaMangoPct / 100) * 10000000;
            var boraSoftW = 10000000 - boraMangoW;
            var boraMangoProd = boraMangoW * 200;
            var boraSoftProd = boraSoftW * 200;
            var costExportMangoes = 0;
            var costImportSoft = 0;
            var tradePrice = period >= 2 ? (d.tradePrice || 0) : 0;
            var policy = period >= 3 ? (d.policy || 'e') : null;
            var grossShipment = 0;
            if (period >= 2) {
                costExportMangoes = Math.min((d.mangoesExported || 0) * 1000000, costMangoProd);
                grossShipment = costExportMangoes;
                // (d) a tariff or quota on the partner's exports: the Trade Ministry's estimate is that it destroys about 9% of the gains, so this season's shipment is cut by 9%
                if (policy === 'd') costExportMangoes = costExportMangoes * 0.91;
                if (tradePrice > 0) costImportSoft = costExportMangoes / tradePrice;
                if (costImportSoft > boraSoftProd) {
                    costImportSoft = boraSoftProd;
                    costExportMangoes = costImportSoft * tradePrice;
                }
            }
            var costMangoCons = costMangoProd - costExportMangoes;
            var costSoftCons = costSoftProd + costImportSoft;
            var boraMangoCons = boraMangoProd + costExportMangoes;
            var boraSoftCons = boraSoftProd - costImportSoft;
            var costPerCapMango = costMangoCons / 2000000;
            var costPerCapSoft = costSoftCons / 2000000;
            var boraPerCapMango = boraMangoCons / 18000000;
            var boraPerCapSoft = boraSoftCons / 18000000;
            var worldMango = costMangoCons + boraMangoCons;
            var worldSoft = costSoftCons + boraSoftCons;
            if (period === 1 && !ds.autarkyBaseline) {
                ds.autarkyBaseline = {
                    costMangoCons: costMangoCons, costSoftCons: costSoftCons,
                    boraMangoCons: boraMangoCons, boraSoftCons: boraSoftCons,
                    worldMango: worldMango, worldSoft: worldSoft,
                    costMangoW: costMangoW, boraMangoW: boraMangoW
                };
            }
            var costariaDisplaced = 0;
            var boraviaDisplaced = 0;
            var policyCost = 0;
            var policyJobsRecovered = 0;
            var policyTradeGainsLost = 0;
            var policyLabel = '';
            var g = this._gains(costExportMangoes / 1000000, tradePrice);
            if (period >= 3) {
                var b = ds.autarkyBaseline;
                if (b) {
                    costariaDisplaced = Math.abs(costMangoW - b.costMangoW);
                    boraviaDisplaced = Math.abs(boraMangoW - b.boraMangoW);
                }
                // gains of both countries at their own pre-trade prices, millions of mango-equivalents
                var grossGains = this._gains(grossShipment / 1000000, tradePrice);
                var gainsValue = Math.max(0, grossGains.c) + Math.max(0, grossGains.b);
                if (policy === 'a') { policyCost = gainsValue * 0.08; }
                else if (policy === 'b') { policyCost = gainsValue * 0.12; }
                else if (policy === 'c') { policyCost = gainsValue * 0.15; }
                else if (policy === 'd') { policyJobsRecovered = 30000; policyTradeGainsLost = gainsValue - (Math.max(0, g.c) + Math.max(0, g.b)); }
                policyLabel = this._t('policy_' + policy + '_short');
            }
            ds.costariaMangoConsHistory.push(costMangoCons);
            ds.costariaSoftConsHistory.push(costSoftCons);
            ds.boraviaMangoConsHistory.push(boraMangoCons);
            ds.boraviaSoftConsHistory.push(boraSoftCons);
            ds.costariaPerCapMangoHistory.push(costPerCapMango);
            ds.costariaPerCapSoftHistory.push(costPerCapSoft);
            ds.boraviaPerCapMangoHistory.push(boraPerCapMango);
            ds.boraviaPerCapSoftHistory.push(boraPerCapSoft);
            ds.worldMangoHistory.push(worldMango);
            ds.worldSoftHistory.push(worldSoft);
            ds.shippedHistory.push(costExportMangoes);
            ds.priceHistory.push(tradePrice);
            ds.costShareHistory.push(d.costariaMangoPct);
            ds.boraShareHistory.push(d.boraviaMangoPct);
            if (period === 2) { ds.scoreTraded = costExportMangoes > 0; ds.scoreTradePrice = tradePrice; }
            if (period === 3) { ds.scorePolicy = policy; ds.displacedTotal = costariaDisplaced + boraviaDisplaced; }
            // platform score: the same composite as the debrief, over the rounds played so far (C1)
            var comp = this._composite(ds);
            ds.performance = Object.assign({}, ds.performance || {}, { overallScore: comp.score, tier: this._tier(comp.score), parts: comp.parts });
            ds.performanceTier = this._tier(comp.score);
            var self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: period + 1 });
            }, 500);
            return {
                period: period,
                costMangoProd: costMangoProd, costSoftProd: costSoftProd,
                boraMangoProd: boraMangoProd, boraSoftProd: boraSoftProd,
                costMangoCons: costMangoCons, costSoftCons: costSoftCons,
                boraMangoCons: boraMangoCons, boraSoftCons: boraSoftCons,
                costPerCapMango: costPerCapMango, costPerCapSoft: costPerCapSoft,
                boraPerCapMango: boraPerCapMango, boraPerCapSoft: boraPerCapSoft,
                worldMango: worldMango, worldSoft: worldSoft,
                tradePrice: tradePrice,
                costExportMangoes: costExportMangoes, costImportSoft: costImportSoft,
                gainCostaria: g.c, gainBoravia: g.b,
                costariaDisplaced: costariaDisplaced, boraviaDisplaced: boraviaDisplaced,
                policyCost: policyCost, policyJobsRecovered: policyJobsRecovered,
                policyTradeGainsLost: policyTradeGainsLost, policyLabel: policyLabel,
                overallScore: comp.score, score: comp.score
            };
        }

        /* each country's gain from the contract at its own pre-trade price (Costaria 2 mangoes per software unit,
           Boravia 1), in millions of mango-equivalents: X(2/p - 1) and X(1 - 1/p). share = the smaller country's
           part of the joint gain, 0 when either side gains nothing */
        _gains(X, p) {
            if (!(X > 0) || !(p > 0)) return { c: 0, b: 0, share: 0 };
            var c = X * (2 / p - 1), b = X * (1 - 1 / p);
            var share = (c > 0 && b > 0) ? Math.min(c, b) / (c + b) : 0;
            return { c: c, b: b, share: share };
        }

        /* one trading season (history index i: 1 = Round 2, 2 = Round 3) scored on what the case's review weighs:
           spec   - world output valued at the contract price (held inside 1-2) against the inherited season of case
                    Exhibit 1 (1,060M mangoes, 1,020M software); full at +1% (both countries' moves now count)
           basket - nobody ends with less of either good than in Round 1, per citizen, in both countries
                    (TN 5.2 and Q5), times a factor that needs both countries to gain at their own prices
           price  - how the gain is split: full when the smaller side gets 15% of the joint gain or more,
                    nothing at the corridor's edges (TN 5.3) or outside it */
        _contractParts(ds, i) {
            var H = function(k) { return Array.isArray(ds[k]) ? ds[k] : []; };
            if (H('costariaPerCapMangoHistory').length <= i) return null;
            var ratio = function(k) {
                var ref = H(k)[0], now = H(k)[i];
                if (!(ref > 0)) return 1;
                return now / ref;
            };
            var X = (H('shippedHistory')[i] || 0) / 1000000;
            var p = H('priceHistory')[i] || 0;
            var g = this._gains(X, p);
            var r = {
                cm: ratio('costariaPerCapMangoHistory'), cs: ratio('costariaPerCapSoftHistory'),
                bm: ratio('boraviaPerCapMangoHistory'), bs: ratio('boraviaPerCapSoftHistory')
            };
            var clamp = function(v) { return Math.max(0, Math.min(1, v)); };
            var keep = function(d) { return clamp(1 - (1 - Math.min(1, d)) / 0.35); };
            var dC = Math.min(r.cm, r.cs), dB = Math.min(r.bm, r.bs);
            var strict = clamp(g.share / 0.05);
            var pv = Math.max(1, Math.min(2, p || 1.5));
            var V = (H('worldMangoHistory')[i] || 0) + pv * (H('worldSoftHistory')[i] || 0);
            var V0 = 1060000000 + pv * 1020000000;
            return {
                spec: clamp(((V - V0) / V0) / 0.01),
                basket: Math.min(keep(dC), keep(dB)) * strict,
                price: clamp(g.share / 0.15),
                ratios: r, gainC: g.c, gainB: g.b, share: g.share, shipped: X, price_: p
            };
        }

        /* one composite for the platform, the per-round score and the debrief (C1): specialisation 20, both
           countries better off in both goods 30, the split of the gain 20 (averaged over the two trading seasons),
           adjustment mechanism 30 (TN 15 rubric weights; the in-class critique is not scorable here) */
        _composite(ds) {
            var parts = [this._contractParts(ds, 1), this._contractParts(ds, 2)].filter(function(x) { return !!x; });
            var avg = function(k) { return parts.length ? parts.reduce(function(s, x) { return s + x[k]; }, 0) / parts.length : 0; };
            var played3 = Array.isArray(ds.costariaPerCapMangoHistory) && ds.costariaPerCapMangoHistory.length >= 3;
            var pol = played3 ? ds.scorePolicy : null;
            var polScore = (pol === 'a' || pol === 'b' || pol === 'c') ? 1 : (pol === 'd' ? 0.3 : 0);
            var p = { spec: avg('spec') * 20, basket: avg('basket') * 30, price: avg('price') * 20, mechanism: polScore * 30 };
            var score = Math.round(p.spec + p.basket + p.price + p.mechanism);
            score = Math.max(0, Math.min(100, score));
            return { score: score, parts: { spec: Math.round(p.spec), basket: Math.round(p.basket), price: Math.round(p.price), mechanism: Math.round(p.mechanism) }, seasons: parts };
        }

        _tier(score) {
            if (score >= 80) return 'excellent';
            if (score >= 60) return 'good';
            if (score >= 40) return 'developing';
            return 'beginner';
        }

        _lang() {
            try { if (window.vcI18n && window.vcI18n._lang) return window.vcI18n._lang; } catch (e) {}
            var h = (document.documentElement && document.documentElement.lang) || 'en';
            return String(h).slice(0, 2);
        }

        _num(v, dec) {
            var s = (+v || 0).toFixed(dec);
            return this._lang() === 'es' ? s.replace('.', ',') : s;
        }

        _fill(key, vals) {
            var s = this._t(key);
            Object.keys(vals || {}).forEach(function(k) { s = s.split('{' + k + '}').join(vals[k]); });
            return s;
        }

        /* what went wrong in this run, read from its own history: a list of {key, cost} in the order they cost points */
        _diagnose(ds) {
            var out = [];
            var shortC = false, shortB = false, overB = false, placeholder = false, edge = null, outside = false, noTrade = false, cSoftShort = false, bSoftShort = false;
            var bShare0 = (ds.boraShareHistory || [])[0];
            for (var i = 1; i <= 2; i++) {
                var c = this._contractParts(ds, i);
                if (!c) continue;
                if (!(c.shipped > 0)) { noTrade = true; continue; }
                if (c.ratios.cm < 0.995) { shortC = true; if (c.shipped >= 60) placeholder = true; }
                if (c.ratios.cs < 0.995) cSoftShort = true;
                if (c.ratios.bm < 0.995) { shortB = true; if ((ds.boraShareHistory || [])[i] < bShare0) overB = true; }
                if (c.ratios.bs < 0.995) bSoftShort = true;
                if (c.gainC < 0 || c.gainB < 0) outside = true;
                else if (c.share < 0.05) edge = edge || { p: c.price_, who: (c.gainB <= c.gainC ? 'boravia' : 'costaria') };
            }
            if (noTrade) out.push({ key: 'dx_no_trade' });
            if (outside) out.push({ key: 'dx_outside' });
            if (edge) out.push({ key: 'dx_edge', vals: { p: this._num(edge.p, 1), who: this._t(edge.who + '_name') } });
            if (placeholder) out.push({ key: 'dx_placeholder' });
            else if (shortC) out.push({ key: 'dx_short_c_mango' });
            if (overB) out.push({ key: 'dx_over_b' });
            else if (shortB) out.push({ key: 'dx_short_b_mango' });
            if (cSoftShort) out.push({ key: 'dx_short_c_soft' });
            if (bSoftShort) out.push({ key: 'dx_short_b_soft' });
            if ((ds.costariaPerCapMangoHistory || []).length >= 3) {
                if (ds.scorePolicy === 'd') out.push({ key: 'dx_tariff' });
                else if (ds.scorePolicy === 'e') out.push({ key: 'dx_nothing', vals: { n: Math.round(ds.displacedTotal || 0).toLocaleString(this._lang() === 'es' ? 'es-ES' : 'en-US') } });
            }
            return out;
        }

        _updateBriefing(state) {
            var period = state.currentPeriod || 1;
            var over = this._isRunComplete(period);
            // the buttons sit in an inner .comp-adv-actions; hiding the outer one also hid the completion panel
            var actions = document.querySelector('.comp-adv-actions .comp-adv-actions') || document.querySelector('.comp-adv-actions');
            if (actions) actions.style.display = over ? 'none' : 'flex';
            var done = document.getElementById('completionPanel');
            if (done) {
                done.style.display = over ? 'block' : 'none';
                if (over && !done.innerHTML) {
                    done.innerHTML = (window.mySimulation && window.mySimulation.lastCompletionHTML) ||
                        ('<div class="comp-adv-debrief"><h3>' + this._t('debrief_heading') + '</h3></div>');
                }
            }
            var briefEl = document.getElementById('briefingText');
            var tradePanel = document.getElementById('tradePanel');
            var policyPanel = document.getElementById('policyPanel');
            var key = 'brief_round1';
            if (period >= 3) key = 'brief_round3';
            else if (period >= 2) key = 'brief_round2';
            if (briefEl && window.mySimulation) briefEl.innerHTML = window.mySimulation.t(key);
            if (tradePanel) tradePanel.style.display = period >= 2 ? 'block' : 'none';
            if (policyPanel) policyPanel.style.display = period >= 3 ? 'block' : 'none';
            if (period >= 3 && window.mySimulation && window.mySimulation.state.domainState.autarkyBaseline) {
                var costEl = document.getElementById('costariaMangoPctInput');
                var boraEl = document.getElementById('boraviaMangoPctInput');
                var costMangoPct = costEl ? parseFloat(costEl.value) : 60;
                var boraMangoPct = boraEl ? parseFloat(boraEl.value) : 50;
                var b = window.mySimulation.state.domainState.autarkyBaseline;
                var cd = Math.abs((costMangoPct / 100) * 1000000 - b.costMangoW);
                var bd = Math.abs((boraMangoPct / 100) * 10000000 - b.boraMangoW);
                var cdEl = document.getElementById('costariaDisplacedDisplay');
                var bdEl = document.getElementById('boraviaDisplacedDisplay');
                if (cdEl) cdEl.textContent = Math.round(cd).toLocaleString();
                if (bdEl) bdEl.textContent = Math.round(bd).toLocaleString();
            }
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('costMangoProd', 'results.costMangoProd', function(v) { return (v / 1000000).toFixed(1) + 'M 🥭'; });
            uiManager.bind('costSoftProd', 'results.costSoftProd', function(v) { return (v / 1000000).toFixed(1) + 'M 💻'; });
            uiManager.bind('boraMangoProd', 'results.boraMangoProd', function(v) { return (v / 1000000).toFixed(1) + 'M 🥭'; });
