        getHint(state, results) {
            if (!results) return null;
            var completed = results.period;
            if (completed === 1) {
                return this._t('hint_after_round1');
            }
            if (completed === 2) {
                var c = this._contractParts(state.domainState || {}, 1);
                if (!c || !(c.shipped > 0)) return this._t('hint_no_trade');
                if (c.gainC < 0 || c.gainB < 0) return this._t('hint_outside_corridor');
                if (c.share < 0.05) return this._t('hint_edge');
                if (c.ratios.cm < 0.995) return this._t('hint_short_c_mango');
                if (c.ratios.bm < 0.995) return this._t('hint_short_b_mango');
                if (c.ratios.cs < 0.995 || c.ratios.bs < 0.995) return this._t('hint_short_soft');
                if (c.spec < 1) return this._t('hint_specialise_more');
                return this._t('hint_gains_realised');
            }
            if (completed === 3) {
                var p = (state.domainState && state.domainState.scorePolicy) || state.decisions.policy || 'e';
                if (p === 'd') return this._t('hint_policy_tariff');
                if (p === 'e') return this._t('hint_policy_nothing');
                return this._t('hint_policy_compensation');
            }
            return null;
        }

