        getPerformanceSummary(history) {
            if (!history || !history.length) return {};
            var st = (window.mySimulation && window.mySimulation.state) || {};
            var ds = st.domainState || {};
            var self = this;
            var comp = this._composite(ds);
            var overall = comp.score;
            var performance = this._tier(overall);
            var perfKey = 'perf_' + performance;
            var insights = [];
            var dx = this._diagnose(ds);
            // the turning point: the costliest part of the score, named from this run's own history (S4)
            var miss = [
                { k: 'basket', max: 30, v: comp.parts.basket }, { k: 'price', max: 20, v: comp.parts.price },
                { k: 'mechanism', max: 30, v: comp.parts.mechanism }, { k: 'spec', max: 20, v: comp.parts.spec }
            ].sort(function(a, b) { return (b.max - b.v) - (a.max - a.v); })[0];
            var keys = dx.map(function(x) { return x.key; });
            var shortfall = keys.some(function(k) { return k.indexOf('dx_short') === 0 || k === 'dx_placeholder' || k === 'dx_over_b'; });
            var traded = keys.indexOf('dx_no_trade') < 0;
            if (miss && miss.max - miss.v >= 3) {
                var tk = (miss.k === 'basket' && !shortfall) ? 'turning_basket_nogain' : 'turning_' + miss.k;
                insights.push(this._fill(tk, { lost: miss.max - miss.v }));
            }
            dx.forEach(function(x) { insights.push(self._fill(x.key, x.vals)); });
            if (!dx.length) insights.push(this._t('summary_all_better'));
            if (comp.parts.mechanism === 30 && traded) insights.push(this._t('summary_compensation_chosen'));
            insights.push(this._t('summary_canonical'));
            var H = function(k) { return Array.isArray(ds[k]) ? ds[k] : []; };
            var last = H('costariaPerCapMangoHistory').length - 1;
            var basket = function(mk, sk, i) { return { m: H(mk)[i], s: H(sk)[i] }; };
            var r3 = history.find(function(h) { return h.results && h.results.period === 3; });
            var policy = ds.scorePolicy || ((r3 && r3.decisions) ? r3.decisions.policy : '') || '';
            return {
                composite: overall,
                overallScore: overall,
                totalScore: overall,
                score: overall,
                parts: comp.parts,
                costariaStart: basket('costariaPerCapMangoHistory', 'costariaPerCapSoftHistory', 0),
                costariaEnd: basket('costariaPerCapMangoHistory', 'costariaPerCapSoftHistory', last),
                boraviaStart: basket('boraviaPerCapMangoHistory', 'boraviaPerCapSoftHistory', 0),
                boraviaEnd: basket('boraviaPerCapMangoHistory', 'boraviaPerCapSoftHistory', last),
                tradePrice: H('priceHistory')[last] || 0,
                policy: policy,
                mistakes: dx.map(function(x) { return x.key; }),
                performance: performance,
                performanceKey: perfKey,
                performanceLabel: this._t(perfKey),
                insights: insights,
                questions: [this._t('dq_1'), this._t('dq_2'), this._t('dq_3')]
            };
        }

        _t(key) {
            if (window.mySimulation && typeof window.mySimulation.t === 'function') {
                var v = window.mySimulation.t(key);
                if (v) return v;
            }
            return key;
        }

        _isRunComplete(period) {
            var st = (window.mySimulation && window.mySimulation.state) || {};
            var maxP = parseInt(st.maxPeriods, 10) || 3;
            var hist = Array.isArray(st.history) ? st.history : [];
            if (hist.length >= maxP) return true;
            return (period || 1) > maxP;
        }

        _syncControlsFromDecisions(state) {
            var dec = (state && state.decisions) || {};
            var map = {
                costariaMangoPctInput: 'costariaMangoPct', boraviaMangoPctInput: 'boraviaMangoPct',
                tradePriceInput: 'tradePrice', mangoesExportedInput: 'mangoesExported'
            };
            Object.keys(map).forEach(function(id) {
                var el = document.getElementById(id);
                var v = dec[map[id]];
                if (el && v !== undefined && v !== null && v !== 0) el.value = String(v);
            });
            var sel = document.getElementById('policySelect');
            if (sel && dec.policy) sel.value = dec.policy;
        }

        formatCompletionMessage(summary) {
            var s = summary || {};
            var self = this;
            var t = function(k) { return self._t(k); };
            var esc = function(v) {
                return String(v === undefined || v === null ? '' : v)
                    .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
            };
            var bk = function(b) { return b && b.m != null ? self._num(b.m, 1) + ' 🥭 / ' + self._num(b.s, 1) + ' 💻' : '—'; };
            var parts = s.parts || {};
            var rows = [
                [t('debrief_costarians'), bk(s.costariaStart) + ' → ' + bk(s.costariaEnd)],
                [t('debrief_boravians'), bk(s.boraviaStart) + ' → ' + bk(s.boraviaEnd)],
                [t('debrief_price'), s.tradePrice ? self._num(s.tradePrice, 1) : '—'],
                [t('debrief_policy'), s.policy ? t('policy_' + s.policy + '_short') : '—']
            ].map(function(r) {
                return '<li><span class="comp-adv-debrief-k">' + esc(r[0]) + '</span>' +
                       '<span class="comp-adv-debrief-v">' + esc(r[1]) + '</span></li>';
            }).join('');
            var sub = [['part_spec', parts.spec, 20], ['part_basket', parts.basket, 30], ['part_price', parts.price, 20], ['part_mechanism', parts.mechanism, 30]].map(function(p) {
                return '<li><span class="comp-adv-debrief-k">' + esc(t(p[0])) + '</span><span class="comp-adv-debrief-v">' + esc((p[1] || 0) + ' / ' + p[2]) + '</span></li>';
            }).join('');
            var ins = (s.insights || []).map(function(x) { return '<p>' + esc(x) + '</p>'; }).join('');
            var qs = (s.questions || []).map(function(x) { return '<li>' + esc(x) + '</li>'; }).join('');
            return '<div class="comp-adv-debrief">' +
                     '<h3>' + esc(t('debrief_heading')) + '</h3>' +
                     '<p class="comp-adv-debrief-headline">' + esc(t('debrief_score')) + ' <strong>' +
                       esc(s.overallScore || 0) + '/100</strong> &middot; ' + esc(s.performanceLabel || '') + '</p>' +
                     '<ul class="comp-adv-debrief-list">' + rows + '</ul>' +
                     '<h4>' + esc(t('debrief_parts')) + '</h4>' +
                     '<ul class="comp-adv-debrief-list">' + sub + '</ul>' +
                     '<div class="comp-adv-debrief-insights">' + ins + '</div>' +
                     '<h4>' + esc(t('debrief_questions')) + '</h4>' +
                     '<ol class="comp-adv-debrief-questions">' + qs + '</ol>' +
                   '</div>';
        }

